SELECT * FROM (	
	SELECT row_number() over()  ROWNUM, LAYERING_NAME FINPROD_ABBR 
	  FROM BOK_ACCT_LAYERING_INFO 
	  WHERE 
	  BUSI_ID = #{busiId}
	  AND BUSI_DETAIL_TYPE = #{busiDetailType}
		union all
	SELECT row_number() over()  ROWNUM, ACCT_SUBJECT_NAME FINPROD_ABBR
	  FROM BOK_ACCT_SUBJECT_INFO 
	  WHERE 
	  ACCT_SUBJECT_ID = #{busiId}
	  AND ACCT_SUBJECT_TYPE = #{busiDetailType}
	  	union all
	SELECT row_number() over()  ROWNUM, FINPROD_ABBR 
	  FROM FIN_PRODUCT 
	  WHERE 
	  FINPROD_ID = #{busiId}
	  AND FINPROD_TYPE = #{busiDetailType}
) WHERE rownum=1


SELECT FINPROD_ABBR FROM (	
	SELECT row_number() over()  ROWNUM, LAYERING_NAME FINPROD_ABBR 
	  FROM BOK_ACCT_LAYERING_INFO 
	  WHERE 
	  BUSI_ID = #{busiId}
	  AND BUSI_DETAIL_TYPE = #{busiDetailType}
	  AND BRANCH = #{branch}
) WHERE rownum=1

SELECT TERM_TYPE 
FROM FIN_TRADE_PRODUCT 
WHERE 
FINPROD_ID = #{busiId}
AND FINPROD_TYPE = #{busiDetailType}
AND BRANCH = 0

SELECT 
  LAYERING_ID 
FROM 
  BOK_ACCT_LAYERING_INFO 
WHERE 
BOOKSET_ID = #{booksetId}	
AND BUSI_ID = #{busiId}	
AND BUSI_DETAIL_TYPE= #{busiDetailType}

select count(*)
from BOK_BOOKSET
where BOOKSET_ID = #{booksetId}

select count(*)
from BOK_ACCT_LAYERING_INFO
where LAYERING_ID = #{layeringId}

    select count(*)
    	from(
		select FINPROD_ID as finprodId
			from FIN_PRODUCT
			where FINPROD_ID = #{finprodId}
			and FINPROD_TYPE = #{finprodType}
		union all 
		select FINPROD_ID as finprodId
			from FIN_TRADE_PRODUCT
			where FINPROD_ID = #{finprodId}
			and FINPROD_TYPE = #{finprodType}
		union all
		select ACCT_NO as finprodId
			from BOK_BOOKSET_CAPACCT_INFO
			where ACCT_NO = #{finprodId}
			and ACCT_TYPE = #{finprodType}
			and BOOKSET_ID = #{booksetId}
		union all 
		select BUSI_ID as finprodId
			from BOK_ACCT_LAYERING_INFO
			where BUSI_ID = #{finprodId}
			and BUSI_DETAIL_TYPE = #{finprodType}
			and BOOKSET_ID = #{booksetId}
		)

   select count(*) from  bok_subject
where SUBJECT_NO=#{subjectNo}
and BASE_SUBJECT_NATURE like  '%CB'
